SELECT worker_id,percentile_cont(0.5) WITHIN GROUP(ORDER BY EXTRACT(EPOCH FROM finished_at-attempt_started_at)),percentile_cont(0.95) WITHIN GROUP(ORDER BY EXTRACT(EPOCH FROM finished_at-attempt_started_at)),percentile_cont(0.5) WITHIN GROUP(ORDER BY EXTRACT(EPOCH FROM finished_at-created_at)),percentile_cont(0.95) WITHIN GROUP(ORDER BY EXTRACT(EPOCH FROM finished_at-created_at)) FROM processing_jobs WHERE status='done' AND finished_at>NOW()-INTERVAL '24 hours' AND attempt_started_at IS NOT NULL GROUP BY worker_id;
